  assign pdvco_en_vco_n_en_wd = reg_wdata[1];

  assign pwm_en_we = addr_hit[6] & reg_we & !reg_error;
  assign pwm_en_wd = reg_wdata[3:0];

  assign dlc_en_we = addr_hit[7] & reg_we & !reg_error;
  assign dlc_en_wd = reg_wdata[0];

  assign dlc_derivative_we = addr_hit[8] & reg_we & !reg_error;
  assign dlc_derivative_wd = reg_wdata[0];

  assign dlc_offset_we = addr_hit[9] & reg_we & !reg_error;
  assign dlc_offset_wd = reg_wdata[5:0];

  assign vco_phase_output_we = addr_hit[13] & reg_we & !reg_error;
  assign vco_phase_output_wd = reg_wdata[0];

  assign dsm_connect_internally_we = addr_hit[15] & reg_we & !reg_error;
  assign dsm_connect_internally_wd = reg_wdata[0];

  assign bpe_connect_internally_we = addr_hit[16] & reg_we & !reg_error;
  assign bpe_connect_internally_wd = reg_wdata[0];

  assign bpe_change_freq_we = addr_hit[17] & reg_we & !reg_error;
  assign bpe_change_freq_wd = reg_wdata[0];

  assign data_out_re = addr_hit[18] & reg_re & !reg_error;

  assign buffer_flush_we = addr_hit[20] & reg_we & !reg_error;
  assign buffer_flush_wd = reg_wdata[0];

  assign data_source_sel_we = addr_hit[21] & reg_we & !reg_error;
  assign data_source_sel_wd = reg_wdata[3:0];

  // Read data return
  always_comb begin
    reg_rdata_next = '0;
    unique case (1'b1)
      addr_hit[0]: begin
        reg_rdata_next[0] = lna_en_qs;
      end

      addr_hit[1]: begin
        reg_rdata_next[0] = buff_en_qs;
      end

      addr_hit[2]: begin
        reg_rdata_next[0] = bpe_en_qs;
      end

      addr_hit[3]: begin
        reg_rdata_next[0] = dsm_en_qs;
      end

      addr_hit[4]: begin
        reg_rdata_next[0] = lc_en_qs;
      end

      addr_hit[5]: begin
        reg_rdata_next[0] = pdvco_en_vco_p_en_qs;
        reg_rdata_next[1] = pdvco_en_vco_n_en_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[3:0] = pwm_en_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[0] = dlc_en_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[0] = dlc_derivative_qs;
      end

      addr_hit[9]: begin
        reg_rdata_next[5:0] = dlc_offset_qs;
      end

      addr_hit[10]: begin
        reg_rdata_next[31:0] = vco_p_out_qs;
      end

      addr_hit[11]: begin
        reg_rdata_next[31:0] = vco_n_out_qs;
      end

      addr_hit[12]: begin
        reg_rdata_next[31:0] = pdvco_out_qs;
      end

      addr_hit[13]: begin
        reg_rdata_next[0] = vco_phase_output_qs;
      end

      addr_hit[14]: begin
        reg_rdata_next[31:0] = dsm_filter_out_qs;
      end

      addr_hit[15]: begin
        reg_rdata_next[0] = dsm_connect_internally_qs;
      end

      addr_hit[16]: begin
        reg_rdata_next[0] = bpe_connect_internally_qs;
      end

      addr_hit[17]: begin
        reg_rdata_next[0] = bpe_change_freq_qs;
      end

      addr_hit[18]: begin
        reg_rdata_next[15:0] = data_out_qs;
      end

      addr_hit[19]: begin
        reg_rdata_next[0] = data_available_qs;
      end

      addr_hit[20]: begin
        reg_rdata_next[0] = buffer_flush_qs;
      end

      addr_hit[21]: begin
        reg_rdata_next[3:0] = data_source_sel_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule

module channel_multipath_reg_top_intf #(
    parameter  int AW = 7,
    localparam int DW = 32
) (
    input logic clk_i,
    input logic rst_ni,
    REG_BUS.in regbus_slave,
    // To HW
    output channel_multipath_reg_pkg::channel_multipath_reg2hw_t reg2hw,  // Write
    input channel_multipath_reg_pkg::channel_multipath_hw2reg_t hw2reg,  // Read
    // Config
    input devmode_i  // If 1, explicit error return for unmapped register access
);
  localparam int unsigned STRB_WIDTH = DW / 8;

  `include "register_interface/typedef.svh"
  `include "register_interface/assign.svh"

  // Define structs for reg_bus
  typedef logic [AW-1:0] addr_t;
  typedef logic [DW-1:0] data_t;
  typedef logic [STRB_WIDTH-1:0] strb_t;
  `REG_BUS_TYPEDEF_ALL(reg_bus, addr_t, data_t, strb_t)

  reg_bus_req_t s_reg_req;
  reg_bus_rsp_t s_reg_rsp;

  // Assign SV interface to structs
  `REG_BUS_ASSIGN_TO_REQ(s_reg_req, regbus_slave)
  `REG_BUS_ASSIGN_FROM_RSP(regbus_slave, s_reg_rsp)



  channel_multipath_reg_top #(
      .reg_req_t(reg_bus_req_t),
      .reg_rsp_t(reg_bus_rsp_t),
      .AW(AW)
  ) i_regs (
      .clk_i,
      .rst_ni,
      .reg_req_i(s_reg_req),
      .reg_rsp_o(s_reg_rsp),
      .reg2hw,  // Write
      .hw2reg,  // Read
      .devmode_i
  );

endmodule


